SELECT * FROM TB_SEARCH_AD_SHOPPING WHERE del_yn = 'N'
AND ad_name LIKE CONCAT('%', #{adName}, '%')
AND ncc_ad_id = #{nccAdId}
AND use_yn = #{useYn}
ORDER BY id DESC

SELECT COUNT(*)
FROM TB_SEARCH_AD_SHOPPING
WHERE del_yn = 'N'

    AND ad_name LIKE CONCAT('%', #{adName}, '%')


    AND ncc_ad_id = #{nccAdId}


    AND use_yn = #{useYn}

SELECT *
FROM TB_SEARCH_AD_SHOPPING_HIST
WHERE shopping_id = #{shoppingId}
ORDER BY id DESC
LIMIT #{limit}
